index 0000000..a77f7de
--- /dev/null
+++ b/internal/mod/mod_test.go.backup
@@ -0,0 +1,431 @@
+package mod_test
+
+import (
+	"reflect"
+	"testing"
+	"time"
+
+	"github.com/psampaz/go-mod-outdated/internal/mod"
+)
+
+var mods = []mod.Module{
+	{
+		Path:     "github.com/pk1/pk1",
+		Main:     true,
+		Indirect: false,
+	},
+	{
+		Path:     "github.com/pk2/pk2",
+		Main:     false,
+		Version:  "v1.0.0",
+		Indirect: false,
+	},
+	{
+		Path:     "github.com/pk3/pk3",
+		Main:     false,
+		Version:  "v1.0.0",
+		Indirect: true,
+	},
+	{
+		Path:     "github.com/pk4/pk4",
+		Main:     false,
+		Version:  "v1.0.0",
+		Indirect: false,
+		Update: &mod.Module{
+			Version: "v1.1.0",
+		},
+	},
+	{
+		Path:     "github.com/pk4/pk4",
+		Main:     false,
+		Version:  "v1.0.0",
+		Indirect: true,
+		Update: &mod.Module{
+			Version: "v1.1.0",
+		},
+	},
+}
+
+func modTime(s string) *time.Time {
+	t, _ := time.Parse(time.RFC3339, s)
+	return &t
+}
+
+func TestFilterModules(t *testing.T) {
+	want := []mod.Module{
+		{
+			Path:     "github.com/pk2/pk2",
+			Main:     false,
+			Version:  "v1.0.0",
+			Indirect: false,
+		},
+		{
+			Path:     "github.com/pk3/pk3",
+			Main:     false,
+			Version:  "v1.0.0",
+			Indirect: true,
+		},
+		{
+			Path:     "github.com/pk4/pk4",
+			Main:     false,
+			Version:  "v1.0.0",
+			Indirect: false,
+			Update: &mod.Module{
+				Version: "v1.1.0",
+			},
+		},
+		{
+			Path:     "github.com/pk4/pk4",
+			Main:     false,
+			Version:  "v1.0.0",
+			Indirect: true,
+			Update: &mod.Module{
+				Version: "v1.1.0",
+			},
+		},
+	}
+
+	if got := mod.FilterModules(mods, false, false); !reflect.DeepEqual(got, want) {
+		t.Errorf("FilterModules() = %v, want %v", got, want)
+	}
+}
+
+func TestFilterModulesHasUpdate(t *testing.T) {
+	want := []mod.Module{
+		{
+			Path:     "github.com/pk4/pk4",
+			Main:     false,
+			Version:  "v1.0.0",
+			Indirect: false,
+			Update: &mod.Module{
+				Version: "v1.1.0",
+			},
+		},
+		{
+			Path:     "github.com/pk4/pk4",
+			Main:     false,
+			Version:  "v1.0.0",
+			Indirect: true,
+			Update: &mod.Module{
+				Version: "v1.1.0",
+			},
+		},
+	}
+
+	if got := mod.FilterModules(mods, true, false); !reflect.DeepEqual(got, want) {
+		t.Errorf("FilterModules() = %v, want %v", got, want)
+	}
+}
+
+func TestFilterModulesIsDirect(t *testing.T) {
+	want := []mod.Module{
+		{
+			Path:     "github.com/pk2/pk2",
+			Main:     false,
+			Version:  "v1.0.0",
+			Indirect: false,
+		},
+		{
+			Path:     "github.com/pk4/pk4",
+			Main:     false,
+			Version:  "v1.0.0",
+			Indirect: false,
+			Update: &mod.Module{
+				Version: "v1.1.0",
+			},
+		},
+	}
+
+	if got := mod.FilterModules(mods, false, true); !reflect.DeepEqual(got, want) {
+		t.Errorf("FilterModules() = %v, want %v", got, want)
+	}
+}
+
+func TestFilterModulesHasUpdateIsDirect(t *testing.T) {
+	want := []mod.Module{
+		{
+			Path:     "github.com/pk4/pk4",
+			Main:     false,
+			Version:  "v1.0.0",
+			Indirect: false,
+			Update: &mod.Module{
+				Version: "v1.1.0",
+			},
+		},
+	}
+
+	if got := mod.FilterModules(mods, true, true); !reflect.DeepEqual(got, want) {
+		t.Errorf("FilterModules() = %v, want %v", got, want)
+	}
+}
+
+func TestModule_InvalidTimestamp(t *testing.T) {
+	var tests = []struct {
+		module           mod.Module
+		invalidTimestamp bool
+		description      string
+	}{
+		{mod.Module{
+		{mod.Module{
+			Update: &mod.Module{},
+			Time: modTime("2018-01-01T00:00:00Z"),
+			Update: &mod.Module{
+				Time: modTime("2017-01-01T00:00:00Z"),
+			},
+		}, false, "New version with invalid timestamp"},
+			Path:     "github.com/pk4/pk4",
+			Main:     false,
+			Version:  "v1.0.0",
+			Time:     modTime("2017-01-01T00:00:00Z"),
+			Indirect: false,
+			Update: &mod.Module{
+				Version: "v1.1.0",
+				Time:    modTime("2018-01-01T00:00:00Z"),
+			},
+		}, false, "Current version older that the latest version"},
+		{mod.Module{
+		{mod.Module{
+			Update: &mod.Module{},
+			Time: modTime("2018-01-01T00:00:00Z"),
+			Update: &mod.Module{
+				Time: modTime("2017-01-01T00:00:00Z"),
+			},
+		}, false, "New version with invalid timestamp"},
+			Path:     "github.com/pk4/pk4",
+			Main:     false,
+			Version:  "v1.0.0",
+			Time:     modTime("2018-01-01T00:00:00Z"),
+			Indirect: false,
+			Update: &mod.Module{
+				Version: "v1.1.0",
+				Time:    modTime("2017-01-01T00:00:00Z"),
+			},
+		}, true, "Current version newer that latest version"},
+		{mod.Module{
+		{mod.Module{
+			Update: &mod.Module{},
+			Time: modTime("2018-01-01T00:00:00Z"),
+			Update: &mod.Module{
+				Time: modTime("2017-01-01T00:00:00Z"),
+			},
+		}, false, "New version with invalid timestamp"},
+			Path:     "github.com/pk4/pk4",
+			Main:     false,
+			Version:  "v1.0.0",
+			Time:     modTime("2018-01-01T00:00:00Z"),
+			Indirect: false,
+		}, false, "No update"},
+		{mod.Module{
+		{mod.Module{
+			Update: &mod.Module{},
+			Time: modTime("2018-01-01T00:00:00Z"),
+			Update: &mod.Module{
+				Time: modTime("2017-01-01T00:00:00Z"),
+			},
+		}, false, "New version with invalid timestamp"},
+			Path:    "github.com/pk4/pk4",
+			Main:    false,
+			Version: "v1.0.0",
+			Replace: &mod.Module{
+				Version: "v1.0.0",
+				Time:    modTime("2018-01-01T00:00:00Z"),
+				Update: &mod.Module{
+					Version: "v1.1.0",
+					Time:    modTime("2017-01-01T00:00:00Z"),
+				},
+			},
+			Update:   nil,
+			Indirect: false,
+		}, true, "Current version newer that latest version in Replace"},
+	}
+
+	for k := range tests {
+		test := tests[k]
+		t.Run(test.description, func(t *testing.T) {
+			i := test.module.InvalidTimestamp()
+			if i != test.invalidTimestamp {
+				t.Errorf("got %v, want %v", i, test.invalidTimestamp)
+			}
+		})
+	}
+}
+
+func TestModule_CurrentVersion(t *testing.T) {
+	var tests = []struct {
+		module      mod.Module
+		version     string
+		description string
+	}{
+		{mod.Module{
+		{mod.Module{
+			Update: &mod.Module{},
+			Time: modTime("2018-01-01T00:00:00Z"),
+			Update: &mod.Module{
+				Time: modTime("2017-01-01T00:00:00Z"),
+			},
+		}, false, "New version with invalid timestamp"},
+			Version:  "v1.0.0",
+			Indirect: false,
+		}, "v1.0.0", "Current version without replace"},
+		{mod.Module{
+		{mod.Module{
+			Update: &mod.Module{},
+			Time: modTime("2018-01-01T00:00:00Z"),
+			Update: &mod.Module{
+				Time: modTime("2017-01-01T00:00:00Z"),
+			},
+		}, false, "New version with invalid timestamp"},
+			Replace: &mod.Module{
+				Version: "v0.0.1",
+			},
+			Version: "v1.0.0",
+		}, "v0.0.1", "Current version with replace"}}
+
+	for k := range tests {
+		test := tests[k]
+		t.Run(test.description, func(t *testing.T) {
+			i := test.module.CurrentVersion()
+			if i != test.version {
+				t.Errorf("got %q, want %q", i, test.version)
+			}
+		})
+	}
+}
+
+func TestModule_NewVersion(t *testing.T) {
+	var tests = []struct {
+		module      mod.Module
+		version     string
+		description string
+	}{
+		{mod.Module{
+		{mod.Module{
+			Update: &mod.Module{},
+			Time: modTime("2018-01-01T00:00:00Z"),
+			Update: &mod.Module{
+				Time: modTime("2017-01-01T00:00:00Z"),
+			},
+		}, false, "New version with invalid timestamp"},
+			Version: "v1.0.0",
+			Update: &mod.Module{
+				Version: "v1.1.0",
+			},
+		}, "v1.1.0", "New version without replace"},
+		{mod.Module{
+		{mod.Module{
+			Update: &mod.Module{},
+			Time: modTime("2018-01-01T00:00:00Z"),
+			Update: &mod.Module{
+				Time: modTime("2017-01-01T00:00:00Z"),
+			},
+		}, false, "New version with invalid timestamp"},
+			Replace: &mod.Module{
+				Version: "v0.0.1",
+				Update: &mod.Module{
+					Version: "v0.0.2",
+				},
+			},
+			Version: "v1.0.0",
+			Update: &mod.Module{
+				Version: "v1.1.0",
+			},
+		}, "v0.0.2", "New version with replace"},
+		{mod.Module{
+		{mod.Module{
+			Update: &mod.Module{},
+			Time: modTime("2018-01-01T00:00:00Z"),
+			Update: &mod.Module{
+				Time: modTime("2017-01-01T00:00:00Z"),
+			},
+		}, false, "New version with invalid timestamp"},
+			Version: "v1.0.0",
+			Update:  nil,
+		}, "", "No update"},
+	}
+
+	for k := range tests {
+		test := tests[k]
+		t.Run(test.description, func(t *testing.T) {
+			i := test.module.NewVersion()
+			if i != test.version {
+				t.Errorf("got %q, want %q", i, test.version)
+			}
+		})
+	}
+}
+
+func TestModule_HasNewVersion(t *testing.T) {
+	var tests = []struct {
+		module      mod.Module
+		hasUpdate   bool
+		description string
+	}{
+		{mod.Module{
+		{mod.Module{
+			Update: &mod.Module{},
+			Time: modTime("2018-01-01T00:00:00Z"),
+			Update: &mod.Module{
+				Time: modTime("2017-01-01T00:00:00Z"),
+			},
+		}, false, "New version with invalid timestamp"},
+			Update: &mod.Module{},
