+
+	"github.com/psampaz/go-mod-outdated/internal/mod"
+)
+
+var mods = []mod.Module{
+	{
+		Path:     "github.com/pk1/pk1",
+		Main:     true,
+		Indirect: false,
+	},
+	{
+		Path:     "github.com/pk2/pk2",
+		Main:     false,
+		Version:  "v1.0.0",
+		Indirect: false,
+	},
+	{
+		Path:     "github.com/pk3/pk3",
+		Main:     false,
+		Version:  "v1.0.0",
+		Indirect: true,
+	},
