+		Path:     "github.com/pk4/pk4",
+		Main:     false,
+		Version:  "v1.0.0",
+		Indirect: false,
+		Update: &mod.Module{
+			Version: "v1.1.0",
+		},
+	},
+	{
+		Path:     "github.com/pk4/pk4",
+		Main:     false,
+		Version:  "v1.0.0",
+		Indirect: true,
+		Update: &mod.Module{
+			Version: "v1.1.0",
+		},
+	},
+}
+
+func modTime(s string) *time.Time {
+	t, _ := time.Parse(time.RFC3339, s)
+	return &t
+}
+
+func TestFilterModules(t *testing.T) {
+	want := []mod.Module{
+		{
+			Path:     "github.com/pk2/pk2",
+			Main:     false,
+			Version:  "v1.0.0",
+			Indirect: false,
+		},
+		{
+			Path:     "github.com/pk3/pk3",
+			Main:     false,
+			Version:  "v1.0.0",
+			Indirect: true,
+		},
+		{
+			Path:     "github.com/pk4/pk4",
+			Main:     false,
+			Version:  "v1.0.0",
+			Indirect: false,
+			Update: &mod.Module{
+				Version: "v1.1.0",
+			},
+		},
+		{
+			Path:     "github.com/pk4/pk4",
+			Main:     false,
+			Version:  "v1.0.0",
+			Indirect: true,
+			Update: &mod.Module{
+				Version: "v1.1.0",
+			},
+		},
+	}
+
+	if got := mod.FilterModules(mods, false, false); !reflect.DeepEqual(got, want) {
+		t.Errorf("FilterModules() = %v, want %v", got, want)
+	}
+}
+
