+func TestModule_InvalidTimestamp(t *testing.T) {
+	var tests = []struct {
+		module           mod.Module
+		invalidTimestamp bool
+		description      string
+	}{
+		{mod.Module{
+		{mod.Module{
+			Update: &mod.Module{},
+			Time: modTime("2018-01-01T00:00:00Z"),
+			Update: &mod.Module{
+				Time: modTime("2017-01-01T00:00:00Z"),
+			},
+		}, false, "New version with invalid timestamp"},
+			Path:     "github.com/pk4/pk4",
+			Main:     false,
+			Version:  "v1.0.0",
+			Time:     modTime("2017-01-01T00:00:00Z"),
+			Indirect: false,
+			Update: &mod.Module{
+				Version: "v1.1.0",
+				Time:    modTime("2018-01-01T00:00:00Z"),
+			},
+		}, false, "Current version older that the latest version"},
+		{mod.Module{
+		{mod.Module{
+			Update: &mod.Module{},
+			Time: modTime("2018-01-01T00:00:00Z"),
+			Update: &mod.Module{
+				Time: modTime("2017-01-01T00:00:00Z"),
+			},
+		}, false, "New version with invalid timestamp"},
+			Path:     "github.com/pk4/pk4",
+			Main:     false,
+			Version:  "v1.0.0",
+			Time:     modTime("2018-01-01T00:00:00Z"),
+			Indirect: false,
+			Update: &mod.Module{
+				Version: "v1.1.0",
+				Time:    modTime("2017-01-01T00:00:00Z"),
+			},
+		}, true, "Current version newer that latest version"},
+		{mod.Module{
+		{mod.Module{
+			Update: &mod.Module{},
+			Time: modTime("2018-01-01T00:00:00Z"),
+			Update: &mod.Module{
+				Time: modTime("2017-01-01T00:00:00Z"),
+			},
+		}, false, "New version with invalid timestamp"},
+			Path:     "github.com/pk4/pk4",
+			Main:     false,
+			Version:  "v1.0.0",
+			Time:     modTime("2018-01-01T00:00:00Z"),
+			Indirect: false,
+		}, false, "No update"},
+		{mod.Module{
+		{mod.Module{
+			Update: &mod.Module{},
+			Time: modTime("2018-01-01T00:00:00Z"),
+			Update: &mod.Module{
+				Time: modTime("2017-01-01T00:00:00Z"),
+			},
+		}, false, "New version with invalid timestamp"},
+			Path:    "github.com/pk4/pk4",
+			Main:    false,
+			Version: "v1.0.0",
+			Replace: &mod.Module{
+				Version: "v1.0.0",
+				Time:    modTime("2018-01-01T00:00:00Z"),
+				Update: &mod.Module{
+					Version: "v1.1.0",
+					Time:    modTime("2017-01-01T00:00:00Z"),
+				},
+			},
+			Update:   nil,
+			Indirect: false,
+		}, true, "Current version newer that latest version in Replace"},
+	}
+
+	for k := range tests {
+		test := tests[k]
+		t.Run(test.description, func(t *testing.T) {
+			i := test.module.InvalidTimestamp()
+			if i != test.invalidTimestamp {
+				t.Errorf("got %v, want %v", i, test.invalidTimestamp)
+			}
+		})
+	}
+}
